// developer-tools · the page. Views are built from the generic components in components/ and the tools' own data from /api/data.
const T=new URLSearchParams(location.search).get('t');
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const home=p=>esc(String(p||'').replace(/^\/Users\/[^/]+/,'~').replace(/^\/home\/[^/]+/,'~'));
const hostName=h=>h==='firebase'?'Firebase':'Vercel';
const hostIcon=h=>h==='firebase'||h==='Firebase'?'flame':h==='vercel'||h==='Vercel'?'triangle':'smartphone';
const nextVer=v=>{if(!v)return'';if(v.includes('+')){const[a,b]=v.split('+');return a+'+'+(Number(b)+1)}const p=v.split('.');if(p.length<3)return'';p[2]=String(Number(p[2].replace(/[^0-9].*$/,''))+1);return p.join('.')};
const dstateText={dns:'waiting for DNS',cert:'up on http, HTTPS soon',live:'live'};
let D=null,ST={busy:null,view:'overview',siteId:null,appKey:null,tab:'run',target:'main',verText:null,notes:'git',notesText:'',mail:true,dry:false,build:'fresh',hist:'all',mailSec:'account',tplKind:'site',accHost:'Vercel',toolSec:'installed',q:'',run:null,openLog:null,role:'to'};
const set=o=>{Object.assign(ST,o);render()};window.set=set;
const enc=encodeURIComponent,dec=decodeURIComponent;
function toHash(){const v=ST.view;let h='#'+v;if(v==='sites'&&ST.siteId)h+='/'+enc(ST.siteId)+'/'+ST.tab;else if(v==='apps'&&ST.appKey)h+='/'+enc(ST.appKey)+'/'+ST.tab;else if(v==='history')h+='/'+enc(ST.hist);else if(v==='mailbox')h+='/'+ST.mailSec+(ST.mailSec==='template'?'/'+ST.tplKind:'');else if(v==='accounts')h+='/'+ST.accHost;else if(v==='tools')h+='/'+ST.toolSec;return h}
function fromHash(){const p=location.hash.replace(/^#/,'').split('/');const v=p[0];if(!['overview','sites','apps','history','mailbox','accounts','tools'].includes(v))return false;ST.view=v;
 if(v==='sites'){if(p[1])ST.siteId=dec(p[1]);if(p[2])ST.tab=p[2]}else if(v==='apps'){if(p[1])ST.appKey=dec(p[1]);if(p[2])ST.tab=p[2]}else if(v==='history'&&p[1])ST.hist=dec(p[1]);else if(v==='mailbox'&&p[1]){ST.mailSec=p[1];if(p[2])ST.tplKind=p[2]}else if(v==='accounts'&&p[1])ST.accHost=p[1];else if(v==='tools'&&p[1])ST.toolSec=p[1];return true}
let SYNC=true;window.addEventListener('hashchange',()=>{if(!SYNC)return;if(fromHash())render()});
function goTo(view,id,tab){history.pushState(null,'',location.pathname+location.search+location.hash);const o={view,tab:tab||'run',openLog:null,run:ST.run&&ST.run.id===id?ST.run:null,drun:ST.drun&&ST.drun.id===id?ST.drun:null};if(view==='sites'&&id)o.siteId=id;if(view==='apps'&&id)o.appKey=id;if(id)Object.assign(o,{target:'main',mail:true,dry:false,notes:'git',verText:null,verMode:null});set(o)}window.open_=goTo;
const site=()=>D.sites.find(s=>s.id===ST.siteId)||null,app=()=>D.apps.find(a=>a.key===ST.appKey)||null;
const dotOf=s=>s.domain?(s.domain===s.url?'live':(s.domain_state||'dns')):'';
const npeople=m=>['to','cc','bcc'].reduce((n,k)=>n+(m[k]||[]).length,0);
const allRuns=()=>{const r=[];D.sites.forEach(s=>s.history.forEach(h=>r.push({t:h.t,when:h.when,name:s.label||s.name,tool:hostName(s.host),version:h.version,target:h.target,link:h.link,mailed:h.mailed,kind:'sites',pid:s.id,go:()=>goTo('sites',s.id)})));D.apps.forEach(a=>a.history.forEach(h=>r.push({t:h.t,when:h.when,name:a.app,tool:'APK',version:h.version,target:h.target,link:h.link,mailed:h.mailed,kind:'apps',pid:a.key,go:()=>goTo('apps',a.key)})));return r.sort((a,b)=>b.t-a.t)};
let RUNS=[];window.goRun=i=>{RUNS[i]&&RUNS[i]()};const act=fn=>{RUNS.push(fn);return `goRun(${RUNS.length-1})`};
const targetWord=t=>t==='apk'?'APK on appho.st':t==='main'?'Main website':'Test version';
const runTile=(h,trailing)=>({title:esc(h.name)+' · '+esc(h.version),subtitle:targetWord(h.target)+' · '+esc(h.when)+(h.mailed?' · mailed '+h.mailed:''),leadingIcon:h.target==='apk'?'smartphone':h.target==='main'?'globe':'flask-conical',leadingColor:h.target==='test'?'var(--info)':'',trailing,onclick:act(h.go)});

/* ── render ── */
let LASTVIEW='';
function render(){if(!D)return;const snap=snapshot();SYNC=false;const h=toHash();if(location.hash!==h)history.replaceState(null,'',location.pathname+location.search+h);SYNC=true;
 document.getElementById('brandv').textContent=(D.hub_version||'')+' · '+(D.channel||'stable');document.getElementById('railm').textContent='127.0.0.1:'+D.port+' · press q to stop';
 const all=allRuns();const items=[['overview','Overview','layout-dashboard',''],['sites','Sites','globe',D.sites.length||''],['apps','Apps','smartphone',D.apps.length||''],['history','History','history',''],['mailbox','Mailbox','mail',''],['accounts','Accounts','users',''],['tools','Tools','wrench','']];
 document.getElementById('nav').innerHTML=items.map(([k,l,i,c])=>`<a class="${ST.view===k?'on':''}" href="#${k}" onclick="event.preventDefault();open_('${k}')">${Icon(i,22)}<span class=l>${l}</span><span class=c>${c}</span></a>`).join('');
 renderRunning();renderSub();renderMain();restore(snap,LASTVIEW!==ST.view);LASTVIEW=ST.view}
function renderRunning(){const el=document.getElementById('running');const r=ST.run&&!ST.run.done?ST.run:ST.drun&&!ST.drun.done?ST.drun:null;if(!r){el.innerHTML='';return}const sx=r.app?D.apps.find(x=>x.key===r.id):D.sites.find(x=>x.id===r.id);const st=stagesOf(fmtLog(r.out),false);const isDom=!!r.op;
 el.innerHTML=`<a class=runpill onclick="open_('${r.app?'apps':'sites'}','${esc(r.id)}','${isDom?'domain':'run'}')">${PulseDot('var(--on-primary-container)',5)}<span class=t><span class=n>${isDom?(r.op==='check'?'Checking domain · ':'Connecting domain · '):r.dry?'Dry run · ':r.app?'Shipping ':'Publishing '}${esc(sx?sx.app||sx.label||sx.name:r.id)}</span><span class=s>${isDom?'Firebase':st.length?st[st.length-1].l:'starting'}</span></span></a>`}

/* ── sub drawer ── */
function renderSub(){const v=ST.view;let title='',add=false,html='',search=false;
 const meta=(t,c)=>Meta(esc(t),c);
 if(v==='overview'){title='Recent';const seen=new Set();const items=[];for(const r of allRuns()){if(seen.has(r.pid))continue;seen.add(r.pid);const p=D.sites.concat(D.apps).find(x=>(x.id||x.key)===r.pid);items.push({title:esc(r.name),subtitle:esc(r.link.replace(/^https?:\/\//,'')),trailing:meta(p?p.last:''),onclick:`open_('${r.kind}','${esc(r.pid)}')`});if(items.length>=8)break}
  html=AppTileGroup({title:'Jump to',items,empty:'<div class=pad>Nothing published yet.</div>'})}
 else if(v==='sites'){title='Sites';add=true;search=true;const q=ST.q.toLowerCase();const by={};D.sites.filter(s=>!q||[s.label,s.name,s.url,s.domain,s.account].some(x=>String(x||'').toLowerCase().includes(q))).forEach(s=>{const k=s.account+'|'+s.host;(by[k]=by[k]||[]).push(s)});
  html=Object.entries(by).map(([k,rows])=>{const [acct,host]=k.split('|');
   return AppTileGroup({collapsible:{key:esc(k),title:hostName(host),subtitle:esc(acct),leadingIcon:hostIcon(host),aside:rows.length,force:!!q},items:rows.map(x=>{const d=dotOf(x);const pend=d==='dns'||d==='cert'?dstateText[d]:'';
    return {title:esc(x.label||x.name),subtitle:esc(pend?x.domain+' · '+pend:(d==='live'?x.domain:x.url)),variant:pend?'Warning':'Normal',selected:x.id===ST.siteId,trailing:ST.run&&!ST.run.done&&ST.run.id===x.id?PulseDot('var(--primary)',5)+meta('running'):meta(x.count?x.count+'× · '+x.last:'new'),onclick:`open_('sites','${esc(x.id)}')`}})})}).join('')||'<div class=pad>'+(q?'Nothing matches.':'No sites yet. Run ship-site once.')+'</div>'}
 else if(v==='apps'){title='Apps';add=true;const by={};D.apps.forEach(a=>{const k=a.user_id||'';(by[k]=by[k]||[]).push(a)});
  html=Object.entries(by).map(([uid,rows])=>{const name=rows[0].account||(uid?'account '+uid.slice(0,6)+'…':'no credentials yet');
   return AppTileGroup({collapsible:{key:'apk|'+esc(uid),title:'appho.st',subtitle:esc(name),leadingIcon:'smartphone',aside:rows.length},items:rows.map(a=>({title:esc(a.app||a.key),subtitle:esc(a.app_id||'no app id'),selected:a.key===ST.appKey,trailing:ST.run&&!ST.run.done&&ST.run.id===a.key?PulseDot('var(--primary)',5)+meta('running'):meta(a.count?a.count+'× · '+a.last:'new'),onclick:`open_('apps','${esc(a.key)}')`}))})}).join('')||'<div class=pad>No apps yet. Run ship-apk once.</div>'}
 else if(v==='history'){title='History';const all=allRuns();const cnt=k=>all.filter(x=>k==='all'||x.kind===k||x.pid===k).length;
  html=AppTileGroup({items:[['all','All runs'],['sites','Sites'],['apps','Apps']].map(([k,t])=>({title:t,selected:ST.hist===k,trailing:meta(cnt(k)),onclick:`set({hist:'${k}'})`}))})
   +AppTileGroup({title:'By project',items:[...D.sites.filter(s=>s.history.length).map(s=>[s.id,s.label||s.name]),...D.apps.filter(a=>a.history.length).map(a=>[a.key,a.app])].map(([k,t])=>({title:esc(t),selected:ST.hist===k,trailing:meta(cnt(k)),onclick:`set({hist:'${esc(k)}'})`}))})}
 else if(v==='mailbox'){title='Mailbox';html=AppTileGroup({items:[{title:'Sending account',subtitle:esc(D.mailbox.user||'not set up yet'),selected:ST.mailSec==='account',onclick:"set({mailSec:'account'})"},{title:'Site template',subtitle:'Sent after a publish',selected:ST.mailSec==='template'&&ST.tplKind==='site',onclick:"set({mailSec:'template',tplKind:'site'})"},{title:'APK template',subtitle:'Sent after an upload',selected:ST.mailSec==='template'&&ST.tplKind==='apk',onclick:"set({mailSec:'template',tplKind:'apk'})"}]})}
 else if(v==='accounts'){title='Accounts';const n=h=>D.accounts.filter(a=>a.host===h).length,ns=h=>D.sites.filter(s=>s.host===h.toLowerCase()).length;const sub=h=>n(h)+' account'+(n(h)===1?'':'s')+' · '+ns(h)+' site'+(ns(h)===1?'':'s');
  html=AppTileGroup({items:['Vercel','Firebase'].map(h=>({title:h,subtitle:sub(h),leadingIcon:hostIcon(h),selected:ST.accHost===h,onclick:`set({accHost:'${h}'})`}))})}
 else{title='Tools';html=AppTileGroup({items:[{title:'Installed',subtitle:D.tools.filter(t=>t.version).length+' tools · '+esc(D.hub_version||''),selected:ST.toolSec==='installed',onclick:"set({toolSec:'installed'})"},{title:'Release channel',subtitle:D.channel==='beta'?'Beta':'Stable',selected:ST.toolSec==='channel',onclick:"set({toolSec:'channel'})"}]})}
 document.getElementById('subt').textContent=title;document.getElementById('subadd').innerHTML=add?AppButton({text:v==='sites'?'Add site':'Add app',variant:'Text',size:'Small',leftIcon:'plus',processing:ST.busy==='link',title:v==='sites'?'Pick the site\'s folder; its Vercel or Firebase config says which project it is':'Pick a Flutter project folder; then its appho.st account on its tab',onclick:v==='sites'?"pickFolder('')":"pickFolder('','app')"}):'';
 document.getElementById('subbody').innerHTML=(search?`<div class=search>${AppTextField({id:'q',value:esc(ST.q),placeholder:'Search',leading:'search',oninput:"ST.q=this.value;renderSub();setTimeout(()=>{const i=document.getElementById('q');i&&i.focus();i&&i.setSelectionRange(99,99)})",onkeydown:"if(event.key==='Escape'){ST.q='';renderSub()}",trailing:ST.q?`<span class=tile-act onclick="ST.q='';renderSub()">${Icon('x',16)}</span>`:''})}</div>`:'')+html}

/* ── main ── */
const header=(t,s,right)=>`<header class=ph><div class=l><h1>${t}</h1>${s?`<span class=summ>${s}</span>`:''}</div>${right||''}</header>`;
const VIEWS={overview:viewOverview,sites:viewProject,apps:viewProject,history:viewHistory,mailbox:viewMailbox,accounts:viewAccounts,tools:viewTools};
function renderMain(){const M=document.getElementById('main');RUNS=[];(VIEWS[ST.view]||viewOverview)(M);const lg=document.getElementById('log');if(lg)lg.scrollTop=lg.scrollHeight}
function viewOverview(M){const all=allRuns();const need=[];if(ST.run&&!ST.run.done){const ra=ST.run.app;const rs=ra?D.apps.find(x=>x.key===ST.run.id):D.sites.find(x=>x.id===ST.run.id);need.push(AppNotice({title:esc(rs?rs.app||rs.label||rs.name:ST.run.id)+(ra?' is shipping':' is publishing'),message:'The build log is on its '+(ra?'Ship':'Publish')+' tab',icon:'upload',actionLabel:'Watch',onAction:act(()=>goTo(ra?'apps':'sites',ST.run.id))}))}
  D.sites.forEach(s=>{const d=dotOf(s);if(d==='dns'||d==='cert')need.push(AppNotice({title:esc(s.domain)+' is '+dstateText[d],message:'Live on '+esc(s.url)+' meanwhile',icon:'clock',variant:'Warning',actionLabel:'Records',onAction:act(()=>goTo('sites',s.id,'domain'))}))});
  if(!D.mailbox.ready)need.push(AppNotice({title:'No mailbox yet',message:'Links are copied, nobody is mailed',icon:'mail',actionLabel:'Mailbox',onAction:act(()=>goTo('mailbox'))}));
  D.apps.filter(a=>!npeople(a.mail)).forEach(a=>need.push(AppNotice({title:esc(a.app)+' has nobody to mail',message:'The link is still copied after each build',icon:'mail',actionLabel:'Add people',onAction:act(()=>goTo('apps',a.key,'email'))})));
  const seen=new Set();const again=[];for(const r of all){if(seen.has(r.pid))continue;seen.add(r.pid);again.push(r);if(again.length>=4)break}
  M.innerHTML=header('Overview',`${D.sites.length} sites on ${new Set(D.sites.map(s=>s.account)).size} accounts · ${D.apps.length} apps · ${all.length} runs recorded`)
   +`<section class=sec><span class=sl>Needs you</span>${need.join('')||'<div class=pad>Nothing. Everything is live and set up.</div>'}</section>`
   +(again.length?`<section class=sec><span class=sl>Ship again</span><div class=actions>${again.map((r,i)=>`<div class=cell><div class="act act-${again.length===1?'single':i===0?'first':i===again.length-1?'last':'middle'}" onclick="${act(r.go)}">${Icon(r.kind==='apps'?'smartphone':'globe',22)}<span class=l>${esc(r.name)}</span></div></div>`).join('')}</div></section>`:'')
   +`<section class="sec tight"><span class=sl>Latest runs</span>${AppTileGroup({items:all.slice(0,6).map(h=>runTile(h)),empty:'<div class=pad>No runs recorded yet. The first publish from here on is listed.</div>'})}</section>`;}
function viewProject(M){const v=ST.view;const isApp=v==='apps';const src=isApp?app():site();if(!src){M.innerHTML=header(isApp?'Apps':'Sites','Pick one on the left'+(isApp?'':', or search')+'.');return}
  const nm=npeople(src.mail),hist=src.history,ver=src.version||'',next=nextVer(ver),main=isApp||ST.target==='main';const live=!isApp&&dotOf(src)==='live';
  const title=isApp?esc(src.app):esc(src.label||src.name);const link=isApp?((src.history[0]||{}).link||''):'https://'+(live?src.domain:src.url);
  const subline=isApp?'appho.st'+(src.account?' · '+esc(src.account):'')+' · '+esc(src.app_id)+' · '+home(src.path):hostName(src.host)+' · '+esc(src.account)+' · '+esc(live?src.domain:src.url)+(src.domain&&!live?' · '+esc(src.domain)+' '+dstateText[dotOf(src)]:'');
  const runningHere=ST.run&&!ST.run.done&&ST.run.id===(isApp?src.key:src.id);const tabs=isApp?[['run',runningHere?PulseDot('var(--primary)',5)+'Shipping':'Ship'],['history','History'+(hist.length?' · '+hist.length:'')],['apphost','appho.st'],['email','Email'+(nm?' · '+nm:'')],['settings','Settings']]:[['run',runningHere?PulseDot('var(--primary)',5)+'Publishing':'Publish'],['history','History'+(hist.length?' · '+hist.length:'')],['domain','Domain'],['email','Email'+(nm?' · '+nm:'')],['settings','Settings']];
  const h1=`<h1>${title}${!isApp&&src.label?` <small>· ${esc(src.name)}</small>`:''}</h1>`;
  const base=isApp?'':src.host==='firebase'?src.id.split('/')[1]+'.web.app':(src.url&&src.url!==src.domain?src.url:src.name+'.vercel.app');
  const links=isApp?[link].filter(Boolean):[...new Set(['https://'+base,src.domain?'https://'+src.domain:''].filter(Boolean))];
  const right=`<div class=links>${links.map(u=>`<span class=linkc><a href="${esc(u)}" target=_blank rel=noopener>${esc(u.replace(/^https?:\/\//,''))}${Icon('external-link',14)}</a><span class=tile-act title="Copy" onclick="copyIcon(this,'${esc(u)}')">${Icon('copy',16)}</span></span>`).join('')}</div>`;
  let body='';
  if(ST.tab==='run')body=runTab(src,isApp,nm,hist,ver,next,main,live);
  else if(ST.tab==='history')body=historyTab(src,hist);
  else if(ST.tab==='domain')body=domainTab(src);
  else if(ST.tab==='settings')body=settingsTab(src,isApp);
  else if(ST.tab==='apphost')body=apphostTab(src);
  else if(ST.tab==='email')body=emailTab(src,isApp,nm);
  M.innerHTML=`<header class=ph><div class=l>${h1}<span class=summ>${subline}</span></div>${right}</header><div class=tabs>${tabs.map(([k,l])=>AppChip({label:l,selected:ST.tab===k,onclick:`set({tab:'${k}',openLog:null})`})).join('')}</div><div class=pbody>${body}</div>`;
}
function viewHistory(M){const all=allRuns().filter(x=>ST.hist==='all'||x.kind===ST.hist||x.pid===ST.hist);const nm={all:'All runs',sites:'Sites',apps:'Apps'}[ST.hist]||(D.sites.find(s=>s.id===ST.hist)||{}).label||(D.sites.find(s=>s.id===ST.hist)||{}).name||(D.apps.find(a=>a.key===ST.hist)||{}).app||'History';
  M.innerHTML=header(esc(nm),'Newest first · the last 100 per project are kept')+`<section class="sec tight">${AppTileGroup({items:all.map(h=>runTile(h,Meta(esc(h.link.replace(/^https?:\/\//,''))))),empty:StateView({icon:'history',title:'Nothing yet',message:'The first run from 2.2.0 on is recorded here.'})})}</section>`;}
function viewMailbox(M){const m=D.mailbox;
  if(ST.mailSec==='account'){M.innerHTML=header('Sending account','Shared by ship-site and ship-apk · the password never reaches this page')+`<section class="sec tight narrow">${m.ready||m.user?AppTileGroup({items:[{title:'Address',subtitle:esc(m.user||'-'),leadingIcon:'at-sign'},{title:'App password',subtitle:m.ready?'Saved':'Not set',leadingIcon:'key-round'},{title:'SMTP host',subtitle:esc(m.host||'-')+' · port '+esc(m.port||'-'),leadingIcon:'server'},{title:'Name people see',subtitle:esc(m.from_name||'-'),leadingIcon:'user'}]}):StateView({icon:'mail',title:'No mailbox yet',message:'Set it up in the terminal: ship-site mailbox, or ship-apk config.'})}<div style="padding-top:12px">${AppButton({text:'Send a test to myself',size:'Medium',leftIcon:'send',enabled:false,title:'Next: the terminal does it today'})}</div></section>`}
  else{const t=D.templates[ST.tplKind]||{};const ex=ST.tplKind==='site'?{name:'there',app:'Sukun Garden',version:'1.0.1',link:'https://sukungarden.com',notes:'\n\nWhat changed:\n- privacy page\n- og-image and llms.txt',sender:m.from_name||m.user||'you'}:{name:'there',app:'Thoub',version:'1.0.0+5',link:'https://appho.st/d/E4FW48PjtX',notes:'\n\nWhat changed:\n- cart badge updates live',sender:m.from_name||m.user||'you'};const fill=s=>String(s||'').replace(/\{(\w+)\}/g,(_,k)=>ex[k]??'');
   M.innerHTML=header(ST.tplKind==='site'?'Site template':'APK template','Plain text in mail.json')+`<section class=two><div class=sec><span class=sl>Template</span>${AppTextField({multiline:true,rows:10,mono:true,readonly:true,value:esc((t.subject||'')+'\n\n'+(t.body||''))})}<span class=hint>{name} · {app} · {version} · {link} · {notes} · {sender} · edit it in the terminal: mailbox › edit the mail template</span></div><div class=sec><span class=sl>Preview</span><div class=prev><span class=to>To someone@example.com</span><span class=sj>${esc(fill(t.subject))}</span>${fill(t.body).split('\n').filter(l=>l.trim()).map(l=>`<span>${esc(l)}</span>`).join('')}</div></div></section>`}
  }
function viewAccounts(M){const rows=D.accounts.filter(a=>a.host===ST.accHost);const isV=ST.accHost==='Vercel';
  M.innerHTML=header(ST.accHost,isV?'Sign-ins kept under ~/.config/ship-site/accounts':'These are the Firebase CLI’s own Google sign-ins')+`<section class="sec tight narrow">${AppTileGroup({variant:'Success',items:rows.map(a=>({title:esc(a.name),subtitle:(isV?(a.team?'Team '+esc(a.scope):'Personal scope'):'Google sign-in')+' · '+D.sites.filter(s=>s.account===a.name).length+' sites',leadingIcon:'user-round-check',trailing:Meta(isV?'Remove':'Sign out','var(--error)')})),empty:`<div class=pad>No ${ST.accHost} account yet.</div>`})}<div style="padding-top:12px">${AppButton({text:'Add a '+ST.accHost+' account',variant:'Outline',size:'Medium',leftIcon:'plus',enabled:false,title:'Signing in opens a browser from the terminal: ship-site accounts'})}</div></section>`;}
function viewTools(M){if(ST.toolSec==='installed'){M.innerHTML=header('Installed','In /usr/local/bin')+`<section class="sec tight narrow">${AppTileGroup({items:D.tools.map(t=>({title:esc(t.name),subtitle:esc(t.what),leadingIcon:t.name==='ship-site'?'globe':t.name==='ship-apk'?'smartphone':'rocket',trailing:Meta(esc(t.version||'not installed'))}))})}<div style="padding-top:12px">${AppButton({text:'Check for updates',size:'Medium',leftIcon:'download',enabled:false,title:'developer-tools install, in the terminal'})}</div></section>`}
  else{M.innerHTML=header('Release channel','Which releases install and update give you')+`<section class="sec tight narrow">${AppTileGroup({items:[{title:'Stable',subtitle:'The latest stable release',leadingIcon:'shield-check',selected:D.channel!=='beta',trailing:D.channel!=='beta'?Icon('check',20):''},{title:'Beta',subtitle:'Newest releases, betas included',leadingIcon:'flask-conical',selected:D.channel==='beta',trailing:D.channel==='beta'?Icon('check',20):''}]})}<span class=hint style="padding:12px 4px 0">The tools are the same files on both channels. Only which release you get differs. Change it in the terminal: developer-tools beta, or developer-tools stable.</span></section>`}}

/* ── Run tab: one tile per question, its control in the trailing slot ── */
window.pick=o=>{const f=document.getElementById('notesfold');if('mail' in o&&f){if(!o.mail){f.classList.add('closed');setTimeout(()=>{Object.assign(ST,o);render()},230);return}Object.assign(ST,o);render();const g=document.getElementById('notesfold');if(g){g.classList.add('closed');requestAnimationFrame(()=>g.classList.remove('closed'))}return}Object.assign(ST,o);render()};
function runTab(src,isApp,nm,hist,ver,next,main,live){
 const r=ST.run&&ST.run.id===(isApp?src.key:src.id)?ST.run:null;const running=!!r&&!r.done;
 if(ST.verText==null||ST.verFor!==(isApp?src.key:src.id)){ST.verText=next||ver;ST.verMode=null;ST.verFor=isApp?src.key:src.id}
 const vt=(ST.verText||'').trim();if(ST.verMode==null)ST.verMode=next?'next':'keep';const verMode=ST.verMode;const vok=verOk(vt,isApp);
 const file=isApp?'pubspec.yaml':'package.json';const addr=live?src.domain:src.url;
 // each question is a tile: what it is on the left, its control in the trailing slot
 const tog=(value,opts)=>AppToggle({value,options:opts.map(([v,l,go])=>({value:v,label:l,onclick:go}))});
 const Q=[];
 if(!isApp)Q.push({title:'Where',subtitle:main?'Updates '+esc(addr):'A preview URL'+(src.host==='firebase'?' for 7 days':'')+'; the main website stays as it is',leadingIcon:'globe',
  trailing:tog(main?'main':'test',[['main','Main website',"pick({target:'main'})"],['test','Test version',"pick({target:'test'})"]])});
 if(main)Q.push({title:'Version',subtitle:`<span id=verhint class="${vok?'':'bad'}">${verHint(vt,isApp,ver)}</span>`,leadingIcon:'tag',
  trailing:`<span class=trail-row onclick="event.stopPropagation()">${AppTextField({id:'vertext',value:esc(vt),placeholder:esc(ver||(isApp?'1.0.0+1':'1.0.0')),mono:true,bad:!vok,attrs:'inputmode=decimal',oninput:'ST.verText=this.value;refreshCmd()'})}${AppButton({text:'Bump',variant:'Outline',size:'Small',enabled:!!next,title:next?(isApp?'Next build · ':'Next patch · ')+next:'',onclick:`ST.verText='${esc(next)}';document.getElementById('vertext').value='${esc(next)}';refreshCmd()`})}</span>`});
 else Q.push({title:'Version',subtitle:'Test versions keep '+esc(ver||'the version')+'; it changes only on the main website',leadingIcon:'tag',enabled:false});
 if(isApp){if(!src.last_apk)ST.build='fresh';Q.push({title:'Build',subtitle:ST.build==='fresh'?'flutter build apk --release, about a minute'+(src.last_apk?'':'; no APK in build/ yet'):'The APK already in build/ · '+esc(src.last_apk),leadingIcon:'hammer',
  trailing:src.last_apk?tog(ST.build,[['fresh','Fresh build',"pick({build:'fresh'})"],['last','Last build',"pick({build:'last'})"]]):''})}
 const who=['to','cc','bcc'].flatMap(k=>(src.mail[k]||[]).map(r=>r.email.split('@')[0])).join(', ');
 if(nm&&!D.mailbox.ready)Q.push({title:'Email',subtitle:nm+(nm===1?' person is':' people are')+' listed, but nothing can send until a mailbox is set up under Mailbox; the link is still copied',leadingIcon:'mail',onclick:"open_('mailbox')"});
 else if(nm)Q.push({title:'Email',subtitle:ST.mail?'To '+esc(who):'The link is still copied when it finishes',leadingIcon:'mail',
  trailing:tog(ST.mail?'yes':'no',[['yes','Send to '+nm,"pick({mail:true})"],['no','Don’t send',"pick({mail:false})"]])});
 else Q.push({title:'Email',subtitle:'Nobody to mail yet; add people in the Email tab. The link is still copied.',leadingIcon:'mail',onclick:"set({tab:'email'})"});
 const notes=nm&&D.mailbox.ready?{title:'Notes',subtitle:ST.notes==='git'?'The commit titles since the last send go in the mail':ST.notes==='text'?'Write what changed, a line or two':'Just the link',leadingIcon:'file-text',
  trailing:tog(ST.notes,[['git','Commit titles',"pick({notes:'git'})"],['text','Write',"if(ST.notes!=='text')pick({notes:'text'})"],['-','No notes',"pick({notes:'-'})"]])}:null;
 // one stack: the questions, then Notes and its textarea inside a fold; positions follow what is open, so the corners stay 16/4
 const notesOpen=!!notes&&ST.mail,textOpen=notesOpen&&ST.notes!=='-';
 const pos=(i,n,more)=>n===1&&!more?'Single':i===0?'First':i===n-1&&!more?'Last':'Middle';
 const tiles=Q.map((q,i)=>AppTile(Object.assign({position:pos(i,Q.length,notesOpen)},q))).join('');
 // under Notes, the same block either way: the commit titles that go in the mail, or the textarea to write your own
 const commits=(src.commits||[]);
 const below=ST.notes==='text'?AppTextField({id:'ntx',multiline:true,value:esc(ST.notesText),placeholder:'What changed in this version',attrs:'autofocus',oninput:'ST.notesText=this.value;refreshCmd()'}):ST.notes==='git'?(commits.length?`<div class=commits><span class=k>In the mail</span>${commits.slice(0,8).map(c=>`<span>${esc(c)}</span>`).join('')}${commits.length>8?`<span class=k>and ${commits.length-8} more</span>`:''}</div>`:`<span class=hint>No commits since the last send; the mail goes with just the link.</span>`):'';
 const notesHtml=notes?`<div class="fold${notesOpen?'':' closed'}" id=notesfold><div>${AppTile(Object.assign({position:textOpen?'Middle':'Last'},notes))}${textOpen?`<div class=gafter>${below}</div>`:''}</div></div>`:'';
 const choices=`<div class=tg-list>${tiles}${notesHtml}</div>`;

 const noFolder=!isApp&&!src.folder;const canGo=isApp?(D.can_ship&&!running&&vok&&src.creds&&!!src.app_id&&!!src.path):(!noFolder&&D.can_publish&&!running&&(vok||!main));
 const goLabel=ST.dry?'Start dry run':isApp?'Build, upload and mail':main?'Publish to main website':'Publish test version';
 const goNote=isApp?(!D.can_ship?'ship-apk is not installed on this computer.':!src.path?'No folder yet; pick the Flutter project under Settings.':!src.app_id||!src.creds?'This app has no appho.st id or credentials yet; add them in the terminal: ship-apk › edit an app.':ST.build==='fresh'&&!ST.dry&&!running?'Building takes about a minute; the log below follows it.':''):noFolder?'Pick the folder above first.':!D.can_publish?'ship-site is not installed on this computer.':main&&!ST.dry&&!running?'You will be asked once more before the main website changes.':'';
 const {tokens,plain,fo}=buildCmd(src,isApp,main,nm,ver,next);
 const linkBanner=noFolder?AppNotice({variant:'Warning',icon:'folder',title:'Not linked to a folder yet',message:'Pick the folder this site is built from; this page then publishes it. Vercel or Firebase config inside is read, nothing else changes.',actionLabel:ST.busy==='link'?'Choosing…':'Pick folder',onAction:`pickFolder('${esc(src.id)}')`})
  :isApp?'':AppTileGroup({title:'Folder',items:[{title:home(src.folder),subtitle:src.static?'static files, published as they are':'built with npm run build',leadingIcon:'folder',actions:[{icon:'folder',title:'Pick another folder',busy:ST.busy==='link',onclick:`pickFolder('${esc(src.id)}')`},{icon:'x',title:'Unlink this folder',busy:ST.busy==='unlink',onclick:`unlinkFolder('${esc(src.id)}','${home(src.folder)}')`}]}]});
 return `<div class=run>${linkBanner}<div class=sec style="gap:16px"><div class=choices style="gap:0">${choices}</div>
  <div class=gorow><label onclick="set({dry:!ST.dry})">${AppSwitch({checked:ST.dry})}Dry run</label>${AppButton({text:goLabel,size:'Large',leftIcon:'upload',id:'gobtn',enabled:canGo,processing:running,onclick:'publish()'})}</div>${goNote?`<div class=gonote>${esc(goNote)}</div>`:''}</div>
  ${Terminal({tool:isApp?'ship-apk':'ship-site',dir:fo,tokens,plain,run:r,kind:'run',hint:'Press the button above, or copy the command and run it in Terminal; the same thing happens either way.'})}</div>`}

/* ── the build log ── */
function buildCmd(src,isApp,main,nm,ver,next){
 const vt=(ST.verText||'').trim();const verFlag=!vt||vt===ver?'keep':vt;
 const Tk=[];const tok=(cls,text)=>Tk.push({cls,text});
 const notesPlain=ST.notes==='-'?'--no-notes':ST.notes==='git'?'--notes git':'--notes "'+(ST.notesText||'…').replace(/"/g,'\\"')+'"';
 if(isApp){tok('c','ship-apk');tok('d','--app');tok('v',src.key);tok('v','--version='+verFlag);tok('d',ST.build==='fresh'?'--fresh':'--last-build')}
 else{tok('c','ship-site');tok('d','--project');tok('v',src.id);tok('d',main?'--prod':'--preview');if(main)tok('v','--version='+verFlag)}
 if(nm){const m=ST.mail&&D.mailbox.ready;tok('d',m?'--mail':'--no-mail');if(m)tok('v',notesPlain)}tok('d','--yes');if(ST.dry)tok('d','--dry-run');const fo=isApp?src.path:src.folder;if(fo)tok('p',fo);
 const tokens=Tk.map(t=>esc(t.cls==='p'?home(t.text):t.text));const plain=Tk.map(t=>/\s/.test(t.text)&&!t.text.startsWith('--notes')?'"'+t.text+'"':t.text).join(' ');
 return {tokens,plain,fo}}
const verOk=(t,isApp)=>!t||(isApp?/^[0-9]+\.[0-9]+\.[0-9]+(\+[0-9]+)?$/:/^[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.]+)?$/).test(t);
const verHint=(t,isApp,cur)=>!t?'Empty keeps '+(cur||'the version as it is'):!verOk(t,isApp)?'Not a version. Numbers like '+(isApp?'1.2.0 or 1.2.0+7 (the +7 is the build number)':'1.2.0, or 1.2.0-beta.1'):t===cur?'Same as now; nothing is written':(isApp?'pubspec.yaml':'package.json')+' will be set to '+t+' before the build';
window.refreshCmd=()=>{const isApp=ST.view==='apps';const src=isApp?app():site();if(!src)return;const nm=npeople(src.mail);const ver=src.version||'';const {tokens,plain}=buildCmd(src,isApp,isApp||ST.target==='main',nm,ver,nextVer(ver));
 const tx=document.querySelector('.console .cmd .tx');if(tx)tx.textContent=tokens.join(' ');const cp=document.querySelector('.console .cp');if(cp)cp.setAttribute('onclick',"copyCmd(this,'"+esc(plain).replace(/'/g,'&#39;')+"')");
 const vf=document.getElementById('vertext');if(vf){const ok=verOk(vf.value.trim(),isApp);vf.closest('.field').classList.toggle('bad',!ok);const h=document.getElementById('verhint');if(h){h.textContent=verHint(vf.value.trim(),isApp,src.version||'');h.classList.toggle('bad',!ok)}const g=document.getElementById('gobtn');if(g)g.disabled=!ok||g.classList.contains('busy')}};
/* ── History / Domain / Email tabs ── */
function historyTab(src,hist){const runs=(src.runs||[]).filter(r=>r.done);
 const logBox=(log,last)=>`<div class="hlog${last?' end':''}">${fmtLog(log).map(logLine).join('')}</div>`;
 const stack=(rows,make)=>{const n=rows.length;return `<div class=tg-list>${rows.map((h,i)=>{const key=make.key(h);const isOpen=ST.openLog===key;const last=i===n-1;const pos=n===1?(isOpen?'First':'Single'):i===0?'First':last&&!isOpen?'Last':'Middle';
  return AppTile(Object.assign({position:pos,trailing:isOpen?Icon('chevron-up',20):Meta('Log','var(--primary)'),onclick:`set({openLog:${isOpen?'null':`'${esc(key)}'`}})`},make.tile(h)))+(isOpen?logBox(h.log,last):'')}).join('')}</div>`};
 const pageRuns=runs.length?`<div class="sec tight"><span class=sl>Runs from this page</span>${stack(runs,{key:r=>'r:'+r.run,tile:r=>({title:(r.dry?'Dry run · ':'')+(r.code===0?'Finished':'Stopped · exit '+r.code),subtitle:esc(r.when)+' · '+esc(r.command.replace(/^\S+\s+/,'')),leadingIcon:r.code===0?'circle-check':'circle-alert',variant:r.code===0?'Normal':'Error',actions:[{icon:'external-link',title:'Open the log file',onclick:`openLog('${r.run}')`}]})})}</div>`:'';
 const shipped=hist.length?`<div class="sec tight">${runs.length?'<span class=sl>Shipped</span>':''}${stack(hist,{key:h=>'h:'+h.t,tile:h=>({title:esc(h.link.replace(/^https?:\/\//,'')),subtitle:esc(h.version)+' · '+targetWord(h.target)+(h.mailed?' · mailed '+h.mailed:'')+' · '+esc(h.when),leadingIcon:h.target==='apk'?'smartphone':h.target==='main'?'globe':'flask-conical',leadingColor:h.target==='test'?'var(--info)':'',trailing:h.log?undefined:`<a href="${esc(h.link)}" target=_blank rel=noopener onclick="event.stopPropagation()">${Icon('external-link',18)}</a>`,onclick:h.log?undefined:`window.open('${esc(h.link)}','_blank')`})})}</div>`:'';
 if(!runs.length&&!hist.length)return StateView({icon:'history',title:'Nothing yet',message:'The first run from 2.2.0 on is recorded here.'});
 return `<div class=sec style="gap:20px">${pageRuns}${shipped}</div>`}
function domainTab(src){const d=dotOf(src);const DR=ST.domres&&ST.domres.id===src.id?ST.domres:null;const st=DR&&DR.state?DR.state:(src.domain?(d||'new'):'');const isFb=src.host==='firebase';
 if(isFb&&src.domain&&st!=='live'&&!DR&&ST.domchk!==src.id){ST.domchk=src.id;setTimeout(()=>domain(src.id,'check',''),50)}
 const busy=op=>ST.busy==='domain:'+op;const checked=DR&&DR.at?' · checked '+new Date(DR.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'';
 // the domain is one tile: its state is the subtitle, its actions are the tile's
 const line=!isFb?'Kept here as a reminder. Add it on vercel.com › '+esc(src.name)+' › Domains, which shows the records to add.'
  :st==='live'?'Live with HTTPS'+(DR&&DR.cert==='TEMPORARY'?', permanent certificate on its way':'')+'. Publishing to the main website updates it; '+esc(src.name)+'.web.app keeps working too.'
  :st==='cert'?'Up on http, HTTPS soon. DNS is through; Firebase is issuing the certificate, usually under an hour.'+checked
  :st==='new'?'Saved, not connected yet. Press Connect to connect it on Firebase and get the records to add.'
  :busy('check')?'Asking Firebase…':'Waiting for DNS. Firebase has not seen your records yet; add them at your registrar, then check again.'+checked;
 const dr=ST.drun&&ST.drun.id===src.id?ST.drun:null;const drunning=!!dr&&!dr.done;
 const acts=[];if(isFb&&st!=='live')acts.push({icon:'refresh-cw',title:'Check again on Firebase',busy:busy('check')||drunning,onclick:`runDomain('${esc(src.id)}','check','')`});
 acts.push({icon:'x',title:isFb?'Disconnect: removes the domain on Firebase and here':'Forget: drops the reminder here',busy:busy('disconnect')||busy('remove'),onclick:`disconnectDomain('${esc(src.id)}','${esc(src.domain)}',${isFb})`});
 const tile=src.domain?AppTileGroup({items:[{title:esc(src.domain),subtitle:line,leadingIcon:st==='live'?'circle-check':isFb?'clock':'globe',variant:st==='live'?'Success':isFb&&st!=='new'?'Warning':'Normal',actions:acts}]}):'';
 const recs=DR&&DR.records&&DR.records.length?`<div class="sec tight"><span class=sl>Add at your registrar</span>${AppTileGroup({items:DR.records.map(r=>({title:esc(r.type)+' · '+esc(r.host),subtitle:`<span class=rec>${esc(r.value)}</span>`,actions:[{icon:'copy',title:'Copy',onclick:`copyIcon(this,'${esc(r.value)}')`}]}))})}<div class=row>${AppButton({text:'Copy all',variant:'Outline',size:'Small',leftIcon:'copy',onclick:`copyCmd(this,'${esc(DR.records.map(r=>r.type+'  '+r.host+'  '+r.value).join('\\n'))}')`})}<span class=hint>Host is the part before ${esc(src.domain.split('.').slice(-2).join('.'))}; @ is the domain itself.</span></div></div>`:'';
 const form=`<div class="sec tight"><span class=sl>${src.domain?'Change it':'Your own domain'}</span><form class=row onsubmit="event.preventDefault();submitDomain('${esc(src.id)}')">${AppTextField({id:'domin',wrapId:'dominw',value:esc(src.domain||''),placeholder:'admin.example.com',style:'flex:1 1 260px',oninput:"document.getElementById('dominw').classList.remove('bad');setMsg('domerr','')"})}${AppButton({text:src.domain?(isFb?'Reconnect':'Save'):(isFb?'Connect':'Save'),size:'Medium',type:'submit',id:'domgo',processing:busy('save')||drunning})}</form><span class=hint>${src.domain?'':isFb?'Served on '+esc(src.url)+' either way; that address keeps working.':'Served on '+esc(src.url)+'. Vercel domains are added on vercel.com; the name is kept here as a reminder.'}</span><div class="msg bad" id=domerr></div><div class=msg id=dommsg></div></div>`;
 const dom=(document.getElementById('domin')||{}).value||src.domain||'<name>';const cmdv=dr&&dr.op==='check'?['ship-site','--project',src.id,'--domain-check','--yes']:['ship-site','--project',src.id,'--domain',dom,'--yes'];
 return `<div class=sec style="gap:20px">${tile}${recs}${form}${Terminal({tool:'ship-site',dir:src.folder,tokens:cmdv.map(esc),plain:cmdv.map(x=>/\s/.test(x)?'"'+x+'"':x).join(' '),run:dr,kind:'domain',hint:'Connect or check runs here; or copy the command and run it in Terminal.'})}</div>`}
window.disconnectDomain=async(id,dom,isFb)=>{if(!(await ask(isFb?'Disconnect '+dom+'?':'Forget '+dom+'?',isFb?'Firebase stops serving it and the records at your registrar stop pointing anywhere. The site stays on its web.app address.':'Only the reminder here goes; nothing changes on Vercel.',isFb?'Disconnect':'Forget')))return;domain(id,isFb?'disconnect':'remove','')};
function settingsTab(src,isApp){
 const name=isApp?'':`<form class=sec onsubmit="event.preventDefault();saveLabel('${esc(src.id)}',document.getElementById('lbl').value)"><span class=sl>Name</span>${AppTextField({id:'lbl',value:esc(src.label||''),placeholder:esc(src.name),attrs:'maxlength=40'})}${AppButton({text:'Save',size:'Medium',type:'submit',fullWidth:true,processing:ST.busy==='label'})}<span class=hint>Your own name for this project: admin, landing, the domain it serves. Blank shows ${esc(src.name)}.</span></form>`;
 const where=isApp?`<form class=sec onsubmit="event.preventDefault();saveApp('${esc(src.key)}',['a-app'])"><span class=sl>App</span>${AppTextField({id:'a-app',value:esc(src.app),placeholder:'App name'})}${AppButton({text:'Save',size:'Medium',type:'submit',fullWidth:true,processing:ST.busy==='app'})}<span class=hint>The name shown in the list and in the mail.</span></form>`
  +AppTileGroup({title:'Folder',items:[{title:home(src.path||'')||'none yet',subtitle:'the Flutter project ship-apk builds',leadingIcon:'folder',actions:[{icon:'folder',title:'Pick another folder',busy:ST.busy==='link',onclick:`pickFolder('${esc(src.key)}','app')`},...(src.path?[{icon:'x',title:'Unlink this folder',busy:ST.busy==='unlink',onclick:`unlinkFolder('${esc(src.key)}','${home(src.path)}','app')`}]:[])]}]})
  :AppTileGroup({title:hostName(src.host),items:[{title:esc(src.account),subtitle:'account',leadingIcon:hostIcon(src.host)},{title:esc(src.id),subtitle:src.host==='firebase'?'project / site · used by ship-site --project':'project id · used by ship-site --project',leadingIcon:'hash'}]});
 const folder=isApp?'':src.folder?AppTileGroup({title:'Folder',items:[{title:home(src.folder),subtitle:src.static?'static files, published as they are':'built with npm run build, then published',leadingIcon:'folder',actions:[{icon:'folder',title:'Pick another folder',busy:ST.busy==='link',onclick:`pickFolder('${esc(src.id)}')`},{icon:'x',title:'Unlink this folder',busy:ST.busy==='unlink',onclick:`unlinkFolder('${esc(src.id)}','${home(src.folder)}')`}]}]})
  :`<div class="sec tight"><span class=sl>Folder</span>${AppNotice({variant:'Warning',icon:'folder',title:'Not linked to a folder yet',message:'Pick the folder this site is built from; its Vercel or Firebase config is read, nothing else changes.',actionLabel:ST.busy==='link'?'Choosing…':'Pick folder',onAction:`pickFolder('${esc(src.id)}')`})}</div>`;
 return `<div class=sec style="gap:20px">${name}${folder}${where}</div>`}
function apphostTab(src){const h=src.history[0];
 return `<div class=sec style="gap:24px"><form class=sec onsubmit="event.preventDefault();saveApp('${esc(src.key)}',['a-acct','a-user','a-id','a-key'])">
   <span class=sl>Account</span><div class=frm2>${AppTextField({id:'a-acct',value:esc(src.account||''),placeholder:'Account holder name'})}${AppTextField({id:'a-user',value:esc(src.user_id||''),placeholder:'user_id',mono:true})}${AppTextField({id:'a-id',value:esc(src.app_id),placeholder:'App id',mono:true})}${AppTextField({id:'a-key',value:esc(src.api_key||''),placeholder:'API key',mono:true})}</div>
   ${AppButton({text:'Save',size:'Medium',type:'submit',fullWidth:true,processing:ST.busy==='app'})}<span class=hint>From appho.st › your app › API. appho.st allows five apps per account, so the account holder's name tells them apart in the list. The free tier rejects APKs over 100 MB.</span></form>
  ${h?`<div class="sec tight"><span class=sl>Last upload</span>${AppTileGroup({items:[{title:esc(h.link.replace(/^https?:\/\//,'')),subtitle:esc(h.version)+' · '+esc(h.when)+(h.mailed?' · mailed '+h.mailed:'')+(src.last_apk?' · '+esc(src.last_apk):''),leadingIcon:'upload',trailing:`<a href="${esc(h.link)}" target=_blank rel=noopener onclick="event.stopPropagation()">${Icon('external-link',18)}</a>`,actions:[{icon:'copy',title:'Copy the link',onclick:`copyIcon(this,'${esc(h.link)}')`}]}]})}</div>`:`<span class=hint>Nothing uploaded from here yet. The link appho.st gives shows here after the first ship.</span>`}</div>`}
function emailTab(src,isApp,nm){const kind=isApp?'app':'site';const id=isApp?src.key:src.id;const ppl=['to','cc','bcc'].flatMap(k=>(src.mail[k]||[]).map(r=>[k,r.email,r.name]));
 const list=ppl.length?AppTileGroup({items:ppl.map(([role,email,name])=>({title:esc(email),subtitle:role.toUpperCase()+(name&&name!==email.split('@')[0]?' · '+esc(name):''),leadingIcon:'user',actions:[{icon:'x',title:'Remove',busy:ST.busy==='people:remove:'+email,onclick:`people('${kind}','${esc(id)}','remove','${role}','${esc(email)}','')`}]}))}):StateView({icon:'mail',title:'Nobody to mail yet',message:'Add someone and the link goes out after each '+(isApp?'upload':'publish')+'.'});
 const roles=AppToggle({value:ST.role||'to',options:['to','cc','bcc'].map(r=>({value:r,label:r.toUpperCase(),onclick:`ST.role='${r}';[...this.parentNode.children].forEach(c=>c.classList.toggle('on',c===this))`}))});
 return `<div class=sec style="gap:16px">${list}<form class=sec onsubmit="event.preventDefault();people('${kind}','${esc(id)}','add',ST.role||'to',document.getElementById('pe').value,document.getElementById('pn').value)"><span class=sl>Add someone</span><div class=frm2>${AppTextField({id:'pn',placeholder:'Name, optional'})}<div class=tall>${roles}</div></div>${AppTextField({id:'pe',placeholder:'name@example.com',attrs:'type=email autocomplete=off'})}${AppButton({text:'Add',size:'Medium',leftIcon:'plus',type:'submit',fullWidth:true,processing:ST.busy==='people:add'})}<span class=hint>TO is addressed, CC is seen by everyone, BCC by nobody. Enter adds; saved into the same list the terminal uses.</span></form>
  <form class=sec onsubmit="event.preventDefault();people('${kind}','${esc(id)}','subject','to','','',document.getElementById('psub').value)"><span class=sl>Subject</span>${AppTextField({id:'psub',value:esc(src.mail.subject||''),placeholder:esc(D.templates[isApp?'apk':'site'].subject||'')})}${AppButton({text:'Save',size:'Medium',type:'submit',fullWidth:true,processing:ST.busy==='people:subject'})}<span class=hint>Blank keeps the template subject. {app} {version} {link} work here too.</span></form><div class=msg id=pmsg></div></div>`}

/* ── actions ── */
// api(path, body): one POST to the page server; an unreachable server or a non-JSON answer comes back as {error}
async function api(path,body){try{const r=await fetch(path+'?t='+T,{method:'POST',body:JSON.stringify(body)});return r.ok?await r.json():{error:'the page server answered '+r.status+'. Restart developer-tools ui.'}}catch(e){return {error:'could not reach the page server'}}}
// withBusy(what, fn): ST.busy names the control that waits (the templates show its spinner) while fn runs
async function withBusy(what,fn){ST.busy=what;render();try{return await fn()}finally{ST.busy=null}}
// refresh(): data again, even when the server says nothing changed, then the page
async function refresh(){LASTDATA='';await load(true);render()}
const fail=(title,message)=>toast({variant:'Error',icon:'circle-alert',title,message,stay:10000});
const done=(title,message)=>toast({variant:'Success',icon:'circle-check',title,message});
window.setMsg=(id,t,ok)=>{const m=document.getElementById(id);if(!m)return;m.textContent=t;m.className='msg'+(t?(ok?' ok':' bad'):'')};
window.copyIcon=(b,s)=>{navigator.clipboard.writeText(s).then(()=>{const was=b.innerHTML;b.innerHTML=Icon('check',18);setTimeout(()=>b.innerHTML=was,1200)}).catch(()=>{})};
window.copyCmd=(b,s)=>{navigator.clipboard.writeText(s).then(()=>{b.textContent='Copied';setTimeout(()=>b.textContent='Copy',1200)}).catch(()=>{})};
window.saveApp=async(key,ids)=>{const names={'a-app':'app','a-id':'app_id','a-user':'user_id','a-key':'api_key','a-acct':'account'};const body={key};ids.forEach(i=>{const e=document.getElementById(i);if(e)body[names[i]]=e.value});
 const j=await withBusy('app',()=>api('/api/app',body));if(j.error){render();return fail('Not saved',j.error)}await refresh();done('Saved','ship-apk uses it from the next ship')};
window.saveLabel=async(id,label)=>{const j=await withBusy('label',()=>api('/api/label',{id,label}));if(j.error){render();return fail('Name not saved',j.error)}await refresh();done(label?'Named '+label:'Name cleared','The list and the terminal show it too')};
window.people=async(kind,id,op,role,email,name,subject)=>{const j=await withBusy('people:'+op+(op==='remove'?':'+email:''),()=>api('/api/people',{kind,id,op,role,email,name,subject}));if(j.error){render();return setMsg('pmsg','✗ '+j.error)}
 if(op==='add'){['pe','pn'].forEach(i=>{const e=document.getElementById(i);if(e)e.value=''});const pe=document.getElementById('pe');pe&&pe.focus()}await refresh();setMsg('pmsg',op==='add'?'✓ added '+email:op==='remove'?'✓ removed '+email:'✓ subject saved',true)};
function ask(title,sub,yes){return new Promise(res=>{const v=document.createElement('div');v.className='veil';v.innerHTML=`<div class=dlg role=dialog aria-modal=true><h3>${esc(title)}</h3><p>${esc(sub)}</p><div class=acts>${AppButton({text:'Cancel',variant:'Text',size:'Small',id:'dno'})}${AppButton({text:esc(yes),size:'Small',id:'dyes'})}</div></div>`;
 const done=ok=>{v.remove();document.removeEventListener('keydown',key);res(ok)};const key=e=>{if(e.key==='Escape')done(false);if(e.key==='Enter')done(true)};document.addEventListener('keydown',key);
 v.addEventListener('click',e=>{if(e.target===v)done(false)});v.querySelector('#dno').onclick=()=>done(false);v.querySelector('#dyes').onclick=()=>done(true);document.body.appendChild(v);v.querySelector('#dyes').focus()})}
window.openLog=async rid=>{const j=await api('/api/open_log',{run:rid});if(j.error)fail('No log',j.error)};
window.openPath=async p=>{const j=await api('/api/open_log',{path:p});if(j.error)fail('Cannot open',j.error)};
window.dismissRun=k=>set(k==='domain'?{drun:null}:{run:null});
window.submitDomain=id=>{const i=document.getElementById('domin');const v=(i.value||'').trim().toLowerCase().replace(/^https?:\/\//,'').split('/')[0].replace(/^www\./,'');const w=document.getElementById('dominw');
 if(!/^([a-z0-9-]+\.)+[a-z]{2,}$/.test(v)){w.classList.add('bad');setMsg('domerr',v?'“'+v+'” is not a domain. Something like example.com or admin.example.com.':'Type the domain first.');i.focus();return}
 w.classList.remove('bad');setMsg('domerr','');i.value=v;runDomain(id,'connect',v)};
window.domain=async(id,op,dom,quiet)=>{if(!quiet)setMsg('dommsg',op==='check'?'Asking Firebase…':op==='remove'?'Forgetting…':op==='disconnect'?'Disconnecting…':'Connecting…',true);
 const j=quiet?await api('/api/domain',{id,op,domain:dom}):await withBusy('domain:'+op,()=>api('/api/domain',{id,op,domain:dom}));ST.domres=Object.assign({id,at:Date.now()},j);
 const sx=D&&D.sites.find(x=>x.id===id);if(sx&&!j.error){if(op==='remove'||op==='disconnect'){sx.domain='';sx.domain_state='';ST.domres=null;if(op==='disconnect'&&sx.url===dom)sx.url=sx.name+'.web.app'}else{sx.domain=j.domain||sx.domain;if(j.state&&j.state!=='new'&&j.state!=='reminder')sx.domain_state=j.state;if(j.state==='live')sx.url=sx.domain}}LASTDATA='';render();
 if(quiet)return;if(j.error)setMsg('dommsg','✗ '+j.error);else if(op==='remove')setMsg('dommsg','✓ forgotten',true);else if(op==='disconnect')setMsg('dommsg','✓ disconnected on Firebase',true);else setMsg('dommsg',(j.state==='live'?'✓ live with HTTPS':j.state==='cert'?'✓ connected; DNS is through, HTTPS on its way':j.state==='dns'?'✓ connected on Firebase; it has not seen your records yet':j.note||'✓ saved')+' · checked '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'}),true)};
async function publish(){if(ST.view==='apps')return shipApp();const s=site();if(!s)return;const main=ST.target==='main';const vt=(ST.verText||'').trim();const version=!vt||vt===s.version?'keep':vt;const notes=ST.notes==='text'?ST.notesText:ST.notes;const mail=npeople(s.mail)>0&&ST.mail&&D.mailbox.ready;
 if(main&&!ST.dry&&!(await ask('Publish to the main website?','This replaces what is live on '+(dotOf(s)==='live'?s.domain:s.url)+(version!=='keep'?' as version '+version:'')+(mail?', and mails the link to '+npeople(s.mail)+' people.':'.'),'Publish')))return;
 ST.run={id:s.id,out:'',done:false,code:null,dry:ST.dry,link:''};render();
 startRun(ST.run,'/api/deploy',{id:s.id,folder:s.folder,target:ST.target,version,notes,mail,dry:ST.dry},publishDone(s,main))}
const publishDone=(s,main)=>async r=>{const m=String(r.out).match(/https?:\/\/\S+/g);if(m&&r.code===0&&!r.dry)r.link=m.filter(u=>!/console\.firebase|vercel\.com\/|googleapis/.test(u)).pop()||'';outcomeToast(r,s,main);render();await load(true)};
window.publish=publish;
async function shipApp(){const a=app();if(!a)return;const vt=(ST.verText||'').trim();const version=!vt||vt===a.version?'keep':vt;const notes=ST.notes==='text'?ST.notesText:ST.notes;const mail=npeople(a.mail)>0&&ST.mail&&D.mailbox.ready;
 if(!ST.dry&&!(await ask('Build and upload '+a.app+'?',(ST.build==='fresh'?'Builds the APK, uploads it to appho.st':'Uploads the last APK to appho.st')+(version!=='keep'?' as '+version:'')+(mail?', and mails the link to '+npeople(a.mail)+' people.':'.'),'Ship')))return;
 ST.run={id:a.key,out:'',done:false,code:null,dry:ST.dry,link:'',app:true};render();
 startRun(ST.run,'/api/ship',{key:a.key,version,fresh:ST.build==='fresh',notes,mail,dry:ST.dry},shipDone(a))}
const shipDone=a=>async r=>{const m=String(r.out).match(/https?:\/\/appho\.st\/\S+/g);if(m&&r.code===0&&!r.dry)r.link=m.pop();outcomeToast(r,a,true);render();await load(true)};
window.unlinkFolder=async(id,f,kind)=>{if(!(await ask('Unlink '+f+'?',(kind==='app'?'The app stays; ship-apk just forgets which folder it builds.':'The site stays; this page just forgets which folder builds it.')+' Pick another afterwards.','Unlink')))return;
 const j=await withBusy('unlink',()=>api('/api/link',{id,op:'unlink',kind}));if(j.error)fail('Not unlinked',j.error);await refresh()};
window.pickFolder=async(id,kind)=>{if(ST.busy==='link')return;ST.busy='link';const btn=document.querySelector('#subadd button');if(!id&&btn){btn.disabled=true;btn.innerHTML='<span class=spin></span>'}else render();
 let j;try{j=await api('/api/link',{id,kind})}finally{ST.busy=null}
 if(j.cancelled)return render();if(j.error){render();return fail('Not linked',j.error)}
 await refresh();if(j.new){done('Added '+esc(j.id),'Now its appho.st account: app id, user_id and API key');return goTo('apps',j.id,'apphost')}done((kind==='app'?'Folder set to ':'Linked to ')+home(j.folder),kind==='app'?'ship-apk builds from there now':'Publish works from here now');if(!id)goTo('sites',j.id,'settings')};
window.runDomain=async(id,op,dom)=>{ST.drun={id,op,out:'',done:false,code:null,dry:false,link:''};render();
 startRun(ST.drun,'/api/domain_run',{id,op,domain:dom},domainDone(id))};
const domainDone=id=>async()=>{LASTDATA='';await load(true);domain(id,'check','',true)};
function outcomeToast(r,s,main){const v=(ST.verText||'').trim();const mailed=(String(r.out).match(/sent to (\d+) address/)||[])[1];const name=s.app||s.label||s.name;const kind=s.app?'apps':'sites';const id=s.app?s.key:s.id;
 if(r.code!==0){const why=(fmtLog(r.out).filter(l=>!l.head).pop()||{}).text||'';return toast({variant:'Error',icon:'circle-alert',title:name+' stopped · exit '+r.code,message:esc(why||'Nothing was published; the log says why'),actionLabel:'Open log',onAction:`openLog('${r.rid||''}')`,stay:15000})}
 if(r.dry)return toast({variant:'Success',icon:'circle-check',title:'Dry run passed · '+name,message:'Everything checked, nothing changed',actionLabel:'Run for real',onAction:`ST.dry=false;open_('${kind}','${esc(id)}');setTimeout(publish,50)`});
 if(!r.link)return toast({variant:'Warning',icon:'circle-alert',title:name+' finished without a link',message:'The log says what happened',actionLabel:'Open log',onAction:`openLog('${r.rid||''}')`,stay:12000});
 toast({variant:'Success',icon:'circle-check',title:(s.app?'Shipped':main?'Published':'Test version')+(v&&main?' '+v:'')+(mailed?' · mailed '+mailed:'')+' · link copied',message:(r.link||'').replace(/^https?:\/\//,''),actionLabel:r.link?'Open link':'',onAction:r.link?`window.open('${esc(r.link)}','_blank')`:'',stay:10000});
 if(r.link)navigator.clipboard.writeText(r.link).catch(()=>{})}

/* ── data ── */
let LASTDATA='';
function snapshot(){const a=document.activeElement;const vals={};document.querySelectorAll('input[id],textarea[id]').forEach(e=>{vals[e.id]=e.value});return {focus:a&&a.id?a.id:null,selStart:a&&a.selectionStart,selEnd:a&&a.selectionEnd,vals,scroll:window.scrollY,log:(document.getElementById('log')||{}).scrollTop}}
function restore(snap,viewChanged){if(!snap||viewChanged)return;for(const [id,v] of Object.entries(snap.vals)){const e=document.getElementById(id);if(e&&e.value!==v&&!e.readOnly)e.value=v}
 if(snap.focus){const e=document.getElementById(snap.focus);if(e){e.focus({preventScroll:true});try{if(snap.selStart!=null)e.setSelectionRange(snap.selStart,snap.selEnd)}catch(_){}}}window.scrollTo(0,snap.scroll);const lg=document.getElementById('log');if(lg&&snap.log!=null)lg.scrollTop=snap.log}
async function load(keep){const r=await fetch('/api/data?t='+T);if(!r.ok){document.body.innerHTML='<div style="padding:60px;color:#404944">Not allowed. Open the page from the link the terminal printed.</div>';return}
 const nd=await r.json();if(window.PAGE_HASH&&nd.page&&nd.page!==window.PAGE_HASH&&!(ST.run&&!ST.run.done)&&!(ST.drun&&!ST.drun.done)){location.reload();return}window.PAGE_HASH=nd.page;
 const txt=JSON.stringify(Object.assign({},nd,{page:0,active:0}));const changed=txt!==LASTDATA;LASTDATA=txt;D=nd;
 attachRuns(nd.active,m=>{const base={id:m.id,out:'',done:false,code:null,dry:!!m.dry,link:''};
  if(m.kind==='publish'){const sx=nd.sites.find(x=>x.id===m.id);return sx?{slot:'run',run:base,onDone:publishDone(sx,true)}:null}
  if(m.kind==='ship'){const ax=nd.apps.find(x=>x.key===m.id);return ax?{slot:'run',run:Object.assign(base,{app:true}),onDone:shipDone(ax)}:null}
  if(m.kind==='domain')return {slot:'drun',run:Object.assign(base,{op:m.op}),onDone:domainDone(m.id)};return null});
 if(!keep)fromHash();if(!ST.siteId&&D.sites.length){const rec=allRuns().find(x=>x.kind==='sites');ST.siteId=rec?rec.pid:(D.sites.find(s=>s.folder)||D.sites[0]).id}if(!ST.appKey&&D.apps.length)ST.appKey=D.apps[0].key;
 if(!keep||changed)render()}
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();if(ST.view!=='sites')set({view:'sites'});const i=document.getElementById('q');i&&i.focus()}});
load();setInterval(()=>{if(!(ST.run&&!ST.run.done)&&!(ST.drun&&!ST.drun.done))load(true)},3000);
